const raw = $input.first().json;
let content;

if (raw.output && Array.isArray(raw.output) && raw.output[0] && raw.output[0].content) {
  const c = raw.output[0].content;
  content = Array.isArray(c) ? (c[0].text || c[0].content) : c;
}

if (!content) {
  content =
    raw.text ||
    raw.content ||
    (raw.message && raw.message.content) ||
    (raw.choices &&
      raw.choices[0] &&
      raw.choices[0].message &&
      raw.choices[0].message.content);
}

if (Array.isArray(content)) {
  content =
    (content[0] && (content[0].text || content[0].content)) ||
    JSON.stringify(content);
}

content = (content || '')
  .toString()
  .replace(/```json|```/g, '')
  .trim();

if (!content) {
  throw new Error('AI node se koi text nahi mila.');
}

const parsed = JSON.parse(content);

const today = new Date().toISOString().split('T')[0];


// ========================================
// WHATSAPP SENDER NUMBER
// ========================================

const senderNumber =
  $('WhatsApp Trigger').item.json.messages[0].from;


// ========================================
// TRANSACTION ID
// ONE MESSAGE = ONE ID
// EXPENSE + PAYMENT = SAME ID
// ========================================

function generateTransactionId() {
  const datePart = today.replace(/-/g, '').substring(2);

  const randomPart = Math.random()
    .toString(36)
    .substring(2, 6)
    .toUpperCase();

  return `TXN-${datePart}-${randomPart}`;
}

const transactionId = generateTransactionId();


// ========================================
// CANONICAL PERSON NAMES
// ========================================

const canonicalNames = {
  "faheem": "Person 1",
  "amir": "Person 2",
  "hussain": "Person 3",
  "shehzad": "Person 4",
  "umair": "Person 5",
  "abdul rahim": "Person 6",
  "sakhawat": "Person 7",
  "shahid": "Person 8",
  "farhat": "Person 9",
  "khuram": "Person 10",
  "salman": "Person 11",
  "waheed": "Person 12",
  "asif": "Person 13",
  "majid": "Person 14",
  "ghulam mustafa": "Person 15",
  "ahmad": "Person 16",
  "shehzadmultan": "Person 17",
  "bilal": "Person 18",
  "fateh": "Person 19",
  "babar": "Person 20",
  "wajahat": "Person 21",
  "mohsin": "Person 22"
};


function normalizePersonName(value) {

  let name = String(value ?? '')
    .trim()
    .replace(/\s+/g, ' ');

  if (!name) return '';

  const key = name.toLowerCase();

  if (canonicalNames[key]) {
    return canonicalNames[key];
  }

  return name
    .toLowerCase()
    .split(' ')
    .filter(Boolean)
    .map(word =>
      word.charAt(0).toUpperCase() + word.slice(1)
    )
    .join(' ');
}


// ========================================
// DATE
// ========================================

let recordDate = today;

if (
  parsed.date &&
  typeof parsed.date === 'string' &&
  parsed.date.toLowerCase() !== 'null' &&
  parsed.date.trim() !== ''
) {
  recordDate = parsed.date.trim();
}


// ========================================
// OUTPUT
// ========================================

const output = [];


// ========================================
// SETTLEMENT DETECTION
// ========================================

const isSettlement =
  parsed.isSettlement === true ||
  !Array.isArray(parsed.splits) ||
  parsed.splits.length === 0;


// ========================================
// EXPENSE ROWS
// ========================================

if (!isSettlement) {

  for (const s of parsed.splits || []) {

    const normalizedPerson =
      normalizePersonName(s.person);

    output.push({
      json: {

        // SAME TRANSACTION ID
        id: transactionId,

        recordType: 'expense',

        date: recordDate,

        category: parsed.category,

        person: normalizedPerson,

        amount: Number(s.amount) || 0,

        detail: parsed.detail || '',

        senderNumber: senderNumber

      }
    });

  }
}


// ========================================
// PAYMENT ROW
// ========================================

output.push({
  json: {

    // SAME TRANSACTION ID
    id: transactionId,

    recordType: 'payment',

    date: recordDate,

    category: isSettlement
      ? 'settlement'
      : parsed.category,

    paidBy:
      normalizePersonName(parsed.paid_by),

    totalAmount:
      Number(parsed.total) || 0,

    detail:
      isSettlement
        ? 'Balance Cleared'
        : (parsed.detail || ''),

    senderNumber: senderNumber

  }
});


return output;

