const messages = $('WhatsApp Trigger').first().json.messages;
const msg = messages && messages[0];
const text = (msg && msg.text && msg.text.body) || '';
const senderNumber = msg && msg.from;

// Find something that looks like TXN-XXXXXX-XXXX in the message
const match = text.match(/TXN-[A-Za-z0-9-]+/i);
const transactionId = match ? match[0].toUpperCase() : null;

if (!transactionId) {
  throw new Error('Delete command mein Transaction ID nahi mili. Sahi format: "delete TXN-XXXXXX-XXXX"');
}

return [{
  json: {
    transactionId,
    senderNumber
  }
}];

const paymentResults = $('Find Payment Row').all();
const expenseResults = $input.all();
const txnId = $('Extract Delete Info').first().json.transactionId;
const senderNumber = $('Extract Delete Info').first().json.senderNumber;

const paymentRow = paymentResults.find(i => i.json && i.json.row_number);
const expenseRows = expenseResults.filter(i => i.json && i.json.row_number);

if (!paymentRow && expenseRows.length === 0) {
  return [{
    json: {
      found: false,
      transactionId: txnId,
      senderNumber
    }
  }];
}

const output = [];

// Sort expense rows highest row number first, so deleting one row doesn't
// shift the row numbers of the rows still waiting to be deleted.
const sortedExpenseRows = [...expenseRows].sort(
  (a, b) => b.json.row_number - a.json.row_number
);

for (const row of sortedExpenseRows) {
  output.push({
    json: {
      sheet: 'expense',
      row_number: row.json.row_number,
      person: row.json.Person,
      amount: row.json.Amount,
      category: row.json.Category,
      transactionId: txnId,
      senderNumber
    }
  });
}

if (paymentRow) {
  output.push({
    json: {
      sheet: 'payment',
      row_number: paymentRow.json.row_number,
      totalAmount: paymentRow.json['Total Amount'],
      paidBy: paymentRow.json['Paid By'],
      date: paymentRow.json['Date'],
      category: paymentRow.json['Category'],
      transactionId: txnId,
      senderNumber
    }
  });
}

return output;

