(() => {
  const items = $('Build Deletion Plan').all().filter(i => i.json.sheet);
  const txnId = $('Extract Delete Info').first().json.transactionId;
  const expenseItems = items.filter(i => i.json.sheet === 'expense');
  const paymentItem = items.find(i => i.json.sheet === 'payment');

  let msg = `🗑️ *Entry Deleted!*\n\n🆔 *Transaction ID:* ${txnId}`;

  if (paymentItem) {
    msg += `\n\n📅 *Date:* ${paymentItem.json.date}\n🏷️ *Category:* ${paymentItem.json.category}\n💰 *Total Amount:* ${paymentItem.json.totalAmount}\n💳 *Paid By:* ${paymentItem.json.paidBy}`;
  }

  if (expenseItems.length) {
    const splitsText = expenseItems.map(i => `• ${i.json.person}: ${i.json.amount}`).join('\n');
    msg += `\n\n👥 *Expense Splits Removed:*\n${splitsText}`;
  }

  msg += `\n\nYe transaction sab sheets se delete kar di gayi hai.`;
  return msg;
})()
}}

